/* =========================================================
   FUTSAL WEBSITE
   COMPLETE MAIN STYLESHEET
   ========================================================= */


/* =========================================================
   ROOT VARIABLES
   ========================================================= */

:root {

    --primary: #6c5ce7;
    --primary-dark: #5141c7;
    --primary-light: #a78bfa;

    --green: #10b981;
    --green-dark: #059669;

    --orange: #f59e0b;
    --blue: #3b82f6;

    --dark: #080c18;
    --dark-2: #101625;
    --dark-3: #161d2e;

    --white: #ffffff;

    --text: #111827;
    --text-light: #6b7280;
    --text-muted: #9ca3af;

    --background: #f7f8fc;
    --card: #ffffff;

    --border: #e5e7eb;

    --shadow:
        0 15px 40px rgba(15, 23, 42, 0.08);

    --shadow-hover:
        0 25px 60px rgba(15, 23, 42, 0.14);

    --radius-small: 10px;
    --radius-medium: 16px;
    --radius-large: 24px;

}


/* =========================================================
   RESET
   ========================================================= */

* {

    margin: 0;

    padding: 0;

    box-sizing: border-box;

}


html {

    scroll-behavior: smooth;

}


body {

    font-family:
        "Inter",
        Arial,
        sans-serif;

    background: var(--background);

    color: var(--text);

    line-height: 1.6;

    overflow-x: hidden;

}


a {

    text-decoration: none;

    color: inherit;

}


button,
input,
textarea,
select {

    font-family: inherit;

}


img {

    max-width: 100%;

    display: block;

}


/* =========================================================
   CONTAINER
   ========================================================= */

.container {

    width: min(
        1180px,
        calc(100% - 40px)
    );

    margin-left: auto;

    margin-right: auto;

}


/* =========================================================
   NAVBAR
   ========================================================= */

.navbar {

    position: fixed;

    top: 0;

    left: 0;

    right: 0;

    height: 76px;

    z-index: 9999;

    background:
        rgba(8, 12, 24, 0.90);

    backdrop-filter:
        blur(18px);

    -webkit-backdrop-filter:
        blur(18px);

    border-bottom:
        1px solid
        rgba(255, 255, 255, 0.08);

}


.nav-container {

    height: 100%;

    display: flex;

    align-items: center;

    justify-content: space-between;

}


/* =========================================================
   LOGO
   ========================================================= */

.logo {

    display: inline-flex;

    align-items: center;

    gap: 10px;

    color: var(--white);

    font-family:
        "Outfit",
        sans-serif;

    font-size: 23px;

    font-weight: 800;

    letter-spacing: -0.5px;

}


.logo-icon {

    width: 43px;

    height: 43px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 13px;

    background:
        linear-gradient(
            135deg,
            var(--primary),
            #9283f8
        );

    color: white;

    box-shadow:
        0 8px 25px
        rgba(108, 92, 231, 0.35);

    font-size: 19px;

}


.logo > span:last-child {

    color: white;

}


/* =========================================================
   NAVIGATION
   ========================================================= */

.nav-links {

    display: flex;

    align-items: center;

    gap: 4px;

}


.nav-links a {

    position: relative;

    padding:
        10px 13px;

    border-radius: 9px;

    color:
        rgba(255, 255, 255, 0.68);

    font-size: 13px;

    font-weight: 600;

    transition:
        color 0.25s ease,
        background 0.25s ease,
        transform 0.25s ease;

}


.nav-links a:hover {

    color: white;

    background:
        rgba(255, 255, 255, 0.07);

}


.nav-links a.active {

    color: white;

}


/* LOGIN */

.nav-links .login-btn {

    margin-left: 8px;

    border:
        1px solid
        rgba(255, 255, 255, 0.15);

}


.nav-links .login-btn:hover {

    border-color:
        rgba(255, 255, 255, 0.3);

}


/* REGISTER */

.nav-links .register-btn {

    color: white;

    background:
        linear-gradient(
            135deg,
            var(--primary),
            #8d7df6
        );

    box-shadow:
        0 8px 20px
        rgba(108, 92, 231, 0.25);

}


.nav-links .register-btn:hover {

    color: white;

    transform:
        translateY(-2px);

    background:
        linear-gradient(
            135deg,
            var(--primary-dark),
            #7868ed
        );

    box-shadow:
        0 12px 25px
        rgba(108, 92, 231, 0.35);

}


/* MOBILE MENU */

.mobile-menu {

    display: none;

    border: none;

    background: transparent;

    color: white;

    font-size: 23px;

    cursor: pointer;

}


/* =========================================================
   HERO
   ========================================================= */

.hero {

    position: relative;

    min-height: 760px;

    display: flex;

    align-items: center;

    overflow: hidden;

    background:

        radial-gradient(
            circle at 75% 20%,
            rgba(108, 92, 231, 0.34),
            transparent 31%
        ),

        radial-gradient(
            circle at 10% 85%,
            rgba(16, 185, 129, 0.12),
            transparent 28%
        ),

        linear-gradient(
            135deg,
            #070b15,
            #10172a 55%,
            #191333
        );

}


/* GRID */

.hero-grid {

    position: absolute;

    inset: 0;

    opacity: 0.13;

    background-image:

        linear-gradient(
            rgba(255,255,255,0.08) 1px,
            transparent 1px
        ),

        linear-gradient(
            90deg,
            rgba(255,255,255,0.08) 1px,
            transparent 1px
        );

    background-size:
        55px 55px;

    mask-image:
        linear-gradient(
            to bottom,
            black,
            transparent
        );

    -webkit-mask-image:
        linear-gradient(
            to bottom,
            black,
            transparent
        );

}


/* HERO GLOW */

.hero-glow {

    position: absolute;

    border-radius: 50%;

    filter: blur(5px);

    pointer-events: none;

}


.hero-glow-one {

    width: 450px;

    height: 450px;

    right: -180px;

    top: 90px;

    background:
        rgba(108, 92, 231, 0.18);

}


.hero-glow-two {

    width: 300px;

    height: 300px;

    left: -160px;

    bottom: -80px;

    background:
        rgba(16, 185, 129, 0.12);

}


/* HERO CONTAINER */

.hero-container {

    position: relative;

    z-index: 2;

    display: grid;

    grid-template-columns:
        1fr 0.9fr;

    align-items: center;

    gap: 70px;

    padding-top: 100px;

    padding-bottom: 70px;

}


/* =========================================================
   HERO CONTENT
   ========================================================= */

.hero-content {

    max-width: 650px;

}


.hero-badge {

    display: inline-flex;

    align-items: center;

    gap: 9px;

    padding:
        8px 14px;

    margin-bottom: 23px;

    border-radius: 100px;

    color:
        #c9c2ff;

    background:
        rgba(108, 92, 231, 0.14);

    border:
        1px solid
        rgba(167, 139, 250, 0.20);

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 0.6px;

}


.live-dot {

    width: 7px;

    height: 7px;

    border-radius: 50%;

    background: #34d399;

    box-shadow:
        0 0 0 4px
        rgba(52, 211, 153, 0.12);

}


.hero h1 {

    margin-bottom: 25px;

    color: white;

    font-family:
        "Outfit",
        sans-serif;

    font-size:
        clamp(
            48px,
            6vw,
            76px
        );

    line-height: 1.02;

    letter-spacing: -3px;

    font-weight: 800;

}


.hero h1 span {

    display: inline;

    background:
        linear-gradient(
            90deg,
            #a78bfa,
            #6c5ce7,
            #34d399
        );

    -webkit-background-clip: text;

    background-clip: text;

    color: transparent;

}


.hero-description {

    max-width: 570px;

    margin-bottom: 31px;

    color:
        rgba(255, 255, 255, 0.64);

    font-size: 16px;

    line-height: 1.85;

}


/* =========================================================
   HERO BUTTONS
   ========================================================= */

.hero-buttons {

    display: flex;

    flex-wrap: wrap;

    gap: 12px;

}


.primary-btn {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 9px;

    min-height: 48px;

    padding:
        13px 20px;

    border-radius: 11px;

    color: white;

    background:
        linear-gradient(
            135deg,
            var(--primary),
            #8c7df4
        );

    font-size: 13px;

    font-weight: 700;

    box-shadow:
        0 12px 28px
        rgba(108, 92, 231, 0.28);

    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        background 0.25s ease;

}


.primary-btn:hover {

    color: white;

    transform:
        translateY(-3px);

    box-shadow:
        0 18px 35px
        rgba(108, 92, 231, 0.40);

}


.secondary-btn {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 9px;

    min-height: 48px;

    padding:
        12px 20px;

    border-radius: 11px;

    color: white;

    background:
        rgba(255,255,255,0.045);

    border:
        1px solid
        rgba(255,255,255,0.14);

    font-size: 13px;

    font-weight: 700;

    transition:
        transform 0.25s ease,
        background 0.25s ease,
        border-color 0.25s ease;

}


.secondary-btn:hover {

    color: white;

    transform:
        translateY(-3px);

    background:
        rgba(255,255,255,0.09);

    border-color:
        rgba(255,255,255,0.24);

}


/* =========================================================
   HERO STATS
   ========================================================= */

.hero-stats {

    display: flex;

    align-items: center;

    gap: 34px;

    margin-top: 42px;

    padding-top: 24px;

    border-top:
        1px solid
        rgba(255,255,255,0.08);

}


.stat strong {

    display: block;

    margin-bottom: 2px;

    color: white;

    font-family:
        "Outfit",
        sans-serif;

    font-size: 25px;

    font-weight: 700;

}


.stat span {

    display: block;

    color:
        rgba(255,255,255,0.40);

    font-size: 9px;

    font-weight: 700;

    letter-spacing: 0.5px;

}


/* =========================================================
   HERO VISUAL
   ========================================================= */

.hero-visual {

    position: relative;

    height: 500px;

    display: flex;

    align-items: center;

    justify-content: center;

}


.hero-card {

    position: relative;

    width:
        min(
            430px,
            100%
        );

    height: 440px;

    padding: 11px;

    border-radius: 28px;

    background:
        rgba(255,255,255,0.07);

    border:
        1px solid
        rgba(255,255,255,0.12);

    box-shadow:
        0 30px 80px
        rgba(0,0,0,0.35);

    backdrop-filter:
        blur(15px);

    transform:
        rotate(2deg);

    transition:
        transform 0.4s ease;

}


.hero-card:hover {

    transform:
        rotate(0deg)
        translateY(-5px);

}


/* STADIUM */

.stadium-image {

    position: relative;

    width: 100%;

    height: 100%;

    overflow: hidden;

    border-radius: 21px;

    background:

        radial-gradient(
            ellipse at center,
            rgba(34,197,94,0.35),
            transparent 40%
        ),

        linear-gradient(
            135deg,
            #152b24,
            #07130f
        );

}


/* FOOTBALL FIELD */

.stadium-image::before {

    content: "";

    position: absolute;

    width: 70%;

    height: 52%;

    left: 15%;

    top: 23%;

    border:
        2px solid
        rgba(255,255,255,0.27);

    border-radius: 5px;

}


.stadium-image::after {

    content: "";

    position: absolute;

    width: 100px;

    height: 100px;

    left: calc(50% - 50px);

    top: calc(50% - 50px);

    border:
        2px solid
        rgba(255,255,255,0.27);

    border-radius: 50%;

}


/* FIELD LINES */

.stadium-overlay {

    position: absolute;

    inset: 0;

    background:

        linear-gradient(
            90deg,
            transparent 49.7%,
            rgba(255,255,255,0.20) 50%,
            transparent 50.3%
        ),

        linear-gradient(
            0deg,
            transparent 75%,
            rgba(255,255,255,0.04) 75%
        );

}


/* STADIUM CONTENT */

.stadium-content {

    position: absolute;

    left: 0;

    right: 0;

    bottom: 52px;

    z-index: 4;

    text-align: center;

}


.football-icon {

    width: 58px;

    height: 58px;

    display: flex;

    align-items: center;

    justify-content: center;

    margin:
        0 auto 13px;

    border-radius: 18px;

    background:
        rgba(255,255,255,0.10);

    border:
        1px solid
        rgba(255,255,255,0.16);

    color: white;

    font-size: 24px;

}


.stadium-content > span {

    color:
        #86efac;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 2px;

}


.stadium-content h2 {

    margin-top: 7px;

    color: white;

    font-family:
        "Outfit",
        sans-serif;

    font-size: 29px;

    line-height: 1.12;

    letter-spacing: -0.8px;

}


/* =========================================================
   FLOATING BOOKING
   ========================================================= */

.floating-booking {

    position: absolute;

    left: -55px;

    bottom: 50px;

    z-index: 10;

    min-width: 245px;

    display: flex;

    align-items: center;

    gap: 12px;

    padding:
        13px 15px;

    border-radius: 15px;

    background:
        rgba(255,255,255,0.97);

    box-shadow:
        0 20px 45px
        rgba(0,0,0,0.25);

    transform:
        rotate(-2deg);

}


.booking-icon {

    width: 42px;

    height: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    flex-shrink: 0;

    border-radius: 11px;

    color:
        var(--primary);

    background:
        #eeebff;

}


.floating-booking span {

    display: block;

    margin-bottom: 2px;

    color:
        #9ca3af;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: 0.8px;

}


.floating-booking strong {

    display: block;

    color:
        #111827;

    font-size: 12px;

}


.booking-arrow {

    margin-left: auto;

    color:
        var(--primary);

    font-size: 13px;

}


/* =========================================================
   FLOATING RATING
   ========================================================= */

.floating-rating {

    position: absolute;

    top: 35px;

    right: -40px;

    z-index: 10;

    display: flex;

    align-items: center;

    gap: 6px;

    padding:
        11px 14px;

    border-radius: 13px;

    color: #111827;

    background:
        rgba(255,255,255,0.96);

    box-shadow:
        0 15px 35px
        rgba(0,0,0,0.23);

}


.floating-rating i {

    color:
        #f59e0b;

    font-size: 13px;

}


.floating-rating strong {

    font-size: 13px;

}


.floating-rating span {

    color:
        #9ca3af;

    font-size: 9px;

}


/* =========================================================
   SECTION COMMON
   ========================================================= */

.grounds-section {

    padding:
        105px 0 110px;

    background:
        #f7f8fc;

}


.section-heading {

    display: flex;

    align-items: flex-end;

    justify-content: space-between;

    gap: 30px;

}


.section-label {

    display: inline-block;

    margin-bottom: 9px;

    color:
        var(--primary);

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 1.5px;

}


.section-heading h2,
.about-content h2 {

    color:
        #111827;

    font-family:
        "Outfit",
        sans-serif;

    font-size: 39px;

    line-height: 1.15;

    letter-spacing: -1.4px;

}


.section-description {

    max-width: 570px;

    margin-top: 10px;

    color:
        var(--text-light);

    font-size: 14px;

}


/* VIEW ALL */

.view-all {

    display: inline-flex;

    align-items: center;

    gap: 8px;

    color:
        var(--primary);

    font-size: 12px;

    font-weight: 700;

    transition:
        gap 0.25s ease;

}


.view-all:hover {

    gap: 12px;

}


/* =========================================================
   GROUND CARDS
   ========================================================= */

.ground-container {

    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 23px;

    margin-top: 35px;

}


.ground-card {

    overflow: hidden;

    border-radius: 20px;

    background:
        white;

    border:
        1px solid
        rgba(15,23,42,0.06);

    box-shadow:
        var(--shadow);

    transition:
        transform 0.3s ease,
        box-shadow 0.3s ease;

}


.ground-card:hover {

    transform:
        translateY(-8px);

    box-shadow:
        var(--shadow-hover);

}


/* GROUND IMAGE */

.ground-image {

    position: relative;

    height: 210px;

    overflow: hidden;

    display: flex;

    align-items: center;

    justify-content: center;

}


.ground-image-one {

    background:

        radial-gradient(
            circle at 50% 35%,
            rgba(34,197,94,0.40),
            transparent 28%
        ),

        linear-gradient(
            135deg,
            #143d2a,
            #071810
        );

}


.ground-image-two {

    background:

        radial-gradient(
            circle at 50% 35%,
            rgba(59,130,246,0.40),
            transparent 28%
        ),

        linear-gradient(
            135deg,
            #132c4b,
            #07111f
        );

}


.ground-image-three {

    background:

        radial-gradient(
            circle at 50% 35%,
            rgba(108,92,231,0.50),
            transparent 28%
        ),

        linear-gradient(
            135deg,
            #29215a,
            #0f0b24
        );

}


.image-overlay {

    position: absolute;

    inset: 0;

    background:

        linear-gradient(
            to bottom,
            transparent 40%,
            rgba(0,0,0,0.40)
        );

}


/* FIELD DECORATION */

.ground-image::before {

    content: "";

    position: absolute;

    width: 65%;

    height: 55%;

    border:
        2px solid
        rgba(255,255,255,0.18);

    border-radius: 5px;

}


.ground-image::after {

    content: "";

    position: absolute;

    width: 75px;

    height: 75px;

    border:
        2px solid
        rgba(255,255,255,0.18);

    border-radius: 50%;

}


/* GROUND ICON */

.ground-image-icon {

    position: relative;

    z-index: 3;

    width: 62px;

    height: 62px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    color: white;

    background:
        rgba(255,255,255,0.10);

    border:
        1px solid
        rgba(255,255,255,0.16);

    backdrop-filter:
        blur(8px);

    font-size: 24px;

}


/* TAG */

.ground-tag {

    position: absolute;

    top: 14px;

    left: 14px;

    z-index: 5;

    padding:
        6px 9px;

    border-radius: 7px;

    color: white;

    background:
        rgba(16,185,129,0.85);

    font-size: 8px;

    font-weight: 800;

    text-transform: uppercase;

    letter-spacing: 0.6px;

}


/* =========================================================
   GROUND CONTENT
   ========================================================= */

.ground-content {

    padding:
        20px;

}


.ground-location {

    display: flex;

    align-items: center;

    gap: 6px;

    margin-bottom: 7px;

    color:
        var(--primary);

    font-size: 10px;

    font-weight: 700;

}


.ground-location i {

    font-size: 10px;

}


.ground-content h3 {

    margin-bottom: 7px;

    color:
        #111827;

    font-family:
        "Outfit",
        sans-serif;

    font-size: 21px;

    font-weight: 700;

}


.ground-description {

    min-height: 46px;

    margin-bottom: 17px;

    color:
        #6b7280;

    font-size: 11px;

    line-height: 1.7;

}


/* GROUND BOTTOM */

.ground-bottom {

    display: flex;

    align-items: center;

    justify-content: space-between;

    padding-top: 15px;

    border-top:
        1px solid
        #f0f1f4;

}


.ground-price strong {

    color:
        #111827;

    font-family:
        "Outfit",
        sans-serif;

    font-size: 17px;

}


.ground-price span {

    color:
        #9ca3af;

    font-size: 9px;

}


/* GROUND BUTTON */

.ground-btn {

    width: 38px;

    height: 38px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    color: white;

    background:
        var(--primary);

    transition:
        transform 0.25s ease,
        background 0.25s ease;

}


.ground-btn:hover {

    color: white;

    transform:
        translateX(3px);

    background:
        var(--primary-dark);

}


/* =========================================================
   ABOUT SECTION
   ========================================================= */

.about-section {

    padding:
        110px 0;

    background:
        white;

}


.about-grid {

    display: grid;

    grid-template-columns:
        0.9fr 1.1fr;

    gap: 80px;

    align-items: center;

}


.about-content {

    max-width: 470px;

}


.about-content h2 {

    margin-bottom: 19px;

}


.about-content h2 span {

    color:
        var(--primary);

}


.about-content p {

    margin-bottom: 27px;

    color:
        #6b7280;

    font-size: 14px;

    line-height: 1.85;

}


/* =========================================================
   FEATURES
   ========================================================= */

.features {

    display: grid;

    grid-template-columns:
        repeat(2, 1fr);

    gap: 15px;

}


.feature-card {

    display: flex;

    align-items: flex-start;

    gap: 13px;

    padding:
        21px;

    border:
        1px solid
        #edf0f4;

    border-radius: 15px;

    background:
        #fafbfc;

    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        background 0.25s ease;

}


.feature-card:hover {

    transform:
        translateY(-4px);

    background:
        white;

    box-shadow:
        0 15px 35px
        rgba(15,23,42,0.08);

}


.feature-icon {

    width: 43px;

    height: 43px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 11px;

    font-size: 16px;

}


.feature-icon.purple {

    color:
        #6c5ce7;

    background:
        #eeebff;

}


.feature-icon.green {

    color:
        #059669;

    background:
        #dff8ed;

}


.feature-icon.orange {

    color:
        #d97706;

    background:
        #fff2d8;

}


.feature-icon.blue {

    color:
        #2563eb;

    background:
        #e5efff;

}


.feature-card h3 {

    margin-bottom: 4px;

    color:
        #111827;

    font-family:
        "Outfit",
        sans-serif;

    font-size: 14px;

}


.feature-card p {

    color:
        #7b8493;

    font-size: 10px;

    line-height: 1.65;

}


/* =========================================================
   CTA SECTION
   ========================================================= */

.cta-section {

    padding:
        0 0 100px;

    background:
        white;

}


.cta-card {

    position: relative;

    min-height: 330px;

    overflow: hidden;

    display: flex;

    align-items: center;

    padding:
        55px 65px;

    border-radius: 27px;

    background:

        radial-gradient(
            circle at 85% 30%,
            rgba(167,139,250,0.24),
            transparent 30%
        ),

        linear-gradient(
            135deg,
            #0a0e1b,
            #17122e
        );

    box-shadow:
        0 25px 60px
        rgba(15,23,42,0.18);

}


/* CTA DECORATION */

.cta-card::before {

    content: "";

    position: absolute;

    width: 330px;

    height: 330px;

    right: -100px;

    bottom: -170px;

    border-radius: 50%;

    border:
        1px solid
        rgba(167,139,250,0.18);

}


.cta-card::after {

    content: "";

    position: absolute;

    width: 200px;

    height: 200px;

    right: 80px;

    top: -100px;

    border-radius: 50%;

    border:
        1px solid
        rgba(167,139,250,0.12);

}


.cta-glow {

    position: absolute;

    width: 280px;

    height: 280px;

    right: 120px;

    top: 20px;

    border-radius: 50%;

    background:
        rgba(108,92,231,0.12);

    filter:
        blur(50px);

}


/* CTA CONTENT */

.cta-content {

    position: relative;

    z-index: 3;

    max-width: 610px;

}


.cta-content .section-label {

    color:
        #a78bfa;

}


.cta-content h2 {

    margin-bottom: 14px;

    color: white;

    font-family:
        "Outfit",
        sans-serif;

    font-size:
        clamp(
            32px,
            4vw,
            47px
        );

    line-height: 1.1;

    letter-spacing: -1.5px;

}


.cta-content h2 span {

    color:
        #a78bfa;

}


.cta-content p {

    max-width: 500px;

    margin-bottom: 25px;

    color:
        rgba(255,255,255,0.55);

    font-size: 13px;

    line-height: 1.8;

}


/* CTA BALL */

.cta-ball {

    position: absolute;

    right: 70px;

    top: 50%;

    z-index: 2;

    width: 170px;

    height: 170px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    color:
        rgba(255,255,255,0.08);

    border:
        1px solid
        rgba(255,255,255,0.09);

    transform:
        translateY(-50%)
        rotate(-15deg);

    font-size: 80px;

}


/* =========================================================
   FOOTER
   ========================================================= */

.footer {

    padding:
        65px 0 25px;

    color:
        rgba(255,255,255,0.65);

    background:
        #080c18;

}


.footer-top {

    display: grid;

    grid-template-columns:
        1.7fr 1fr 1fr 1fr;

    gap: 50px;

    padding-bottom: 45px;

    border-bottom:
        1px solid
        rgba(255,255,255,0.07);

}


.footer-brand p {

    max-width: 250px;

    margin-top: 16px;

    color:
        rgba(255,255,255,0.38);

    font-size: 11px;

    line-height: 1.8;

}


.footer-links {

    display: flex;

    flex-direction: column;

    align-items: flex-start;

    gap: 9px;

}


.footer-links h4 {

    margin-bottom: 6px;

    color: white;

    font-size: 12px;

    font-weight: 700;

}


.footer-links a {

    color:
        rgba(255,255,255,0.43);

    font-size: 10px;

    transition:
        color 0.2s ease,
        transform 0.2s ease;

}


.footer-links a:hover {

    color:
        #a78bfa;

    transform:
        translateX(3px);

}


/* SOCIAL */

.social-links {

    display: flex;

    gap: 8px;

}


.social-links a {

    width: 34px;

    height: 34px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 9px;

    color:
        rgba(255,255,255,0.55);

    background:
        rgba(255,255,255,0.06);

    transition:
        0.25s ease;

}


.social-links a:hover {

    color: white;

    background:
        var(--primary);

    transform:
        translateY(-3px);

}


/* FOOTER BOTTOM */

.footer-bottom {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding-top: 23px;

}


.footer-bottom p {

    color:
        rgba(255,255,255,0.30);

    font-size: 9px;

}


/* =========================================================
   RESPONSIVE - TABLET
   ========================================================= */

@media (max-width: 1000px) {


    .hero-container {

        grid-template-columns:
            1fr;

        gap: 40px;

        text-align: center;

    }


    .hero-content {

        max-width: 700px;

        margin:
            0 auto;

    }


    .hero-description {

        margin-left: auto;

        margin-right: auto;

    }


    .hero-buttons {

        justify-content: center;

    }


    .hero-stats {

        justify-content: center;

    }


    .hero-visual {

        height: 450px;

    }


    .ground-container {

        grid-template-columns:
            repeat(2, 1fr);

    }


    .ground-card:last-child {

        grid-column:
            1 / -1;

        max-width: 390px;

        width: 100%;

        margin: auto;

    }


    .about-grid {

        grid-template-columns:
            1fr;

        gap: 45px;

    }


    .about-content {

        max-width: 650px;

    }


    .footer-top {

        grid-template-columns:
            2fr 1fr 1fr;

    }


    .footer-brand {

        grid-column:
            1 / -1;

    }

}


/* =========================================================
   RESPONSIVE - MOBILE
   ========================================================= */

@media (max-width: 760px) {


    .container {

        width:
            min(
                100% - 28px,
                600px
            );

    }


    /* NAVBAR */

    .navbar {

        height: 68px;

    }


    .nav-container {

        padding:
            0 2px;

    }


    .logo {

        font-size: 20px;

    }


    .logo-icon {

        width: 39px;

        height: 39px;

        border-radius: 11px;

    }


    .mobile-menu {

        display: block;

    }


    .nav-links {

        position: absolute;

        top: 68px;

        left: 14px;

        right: 14px;

        display: none;

        flex-direction: column;

        align-items: stretch;

        gap: 4px;

        padding: 12px;

        border-radius: 15px;

        background:
            rgba(12,16,29,0.98);

        border:
            1px solid
            rgba(255,255,255,0.08);

        box-shadow:
            0 20px 40px
            rgba(0,0,0,0.30);

    }


    .nav-links.mobile-open {

        display: flex;

    }


    .nav-links a {

        width: 100%;

        padding:
            12px;

        text-align: center;

    }


    .nav-links .login-btn {

        margin-left: 0;

        margin-top: 5px;

    }


    /* HERO */

    .hero {

        min-height: auto;

    }


    .hero-container {

        padding-top: 125px;

        padding-bottom: 75px;

    }


    .hero h1 {

        font-size:
            clamp(
                43px,
                13vw,
                60px
            );

        letter-spacing:
            -2px;

    }


    .hero-description {

        font-size: 13px;

        line-height: 1.75;

    }


    .hero-buttons {

        flex-direction: column;

    }


    .primary-btn,
    .secondary-btn {

        width: 100%;

    }


    .hero-stats {

        gap: 17px;

        justify-content:
            space-between;

    }


    .stat strong {

        font-size: 21px;

    }


    .stat span {

        font-size: 7px;

    }


    /* HERO VISUAL */

    .hero-visual {

        height: 390px;

    }


    .hero-card {

        width:
            min(
                330px,
                90%
            );

        height: 350px;

    }


    .stadium-content {

        bottom: 42px;

    }


    .stadium-content h2 {

        font-size: 24px;

    }


    .floating-booking {

        left: -10px;

        bottom: 30px;

        min-width: 205px;

    }


    .floating-rating {

        right: -5px;

        top: 20px;

    }


    /* SECTIONS */

    .grounds-section {

        padding:
            75px 0;

    }


    .section-heading {

        display: block;

    }


    .section-heading h2,
    .about-content h2 {

        font-size: 32px;

    }


    .view-all {

        margin-top: 16px;

    }


    .section-description {

        font-size: 12px;

    }


    /* GROUNDS */

    .ground-container {

        grid-template-columns:
            1fr;

    }


    .ground-card:last-child {

        grid-column:
            auto;

        max-width: none;

    }


    /* ABOUT */

    .about-section {

        padding:
            75px 0;

    }


    .features {

        grid-template-columns:
            1fr;

    }


    .feature-card {

        padding: 18px;

    }


    /* CTA */

    .cta-section {

        padding:
            0 0 75px;

    }


    .cta-card {

        min-height:
            390px;

        padding:
            38px 27px;

    }


    .cta-content h2 {

        font-size: 34px;

    }


    .cta-ball {

        right: -20px;

        bottom: -35px;

        top: auto;

        width: 150px;

        height: 150px;

        transform:
            rotate(-15deg);

        font-size: 70px;

    }


    /* FOOTER */

    .footer {

        padding:
            50px 0 20px;

    }


    .footer-top {

        grid-template-columns:
            repeat(2, 1fr);

        gap: 35px 25px;

    }


    .footer-brand {

        grid-column:
            1 / -1;

    }


    .footer-bottom {

        flex-direction:
            column;

        align-items:
            flex-start;

    }

}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 430px) {


    .hero h1 {

        font-size: 42px;

    }


    .hero-stats {

        gap: 10px;

    }


    .stat strong {

        font-size: 18px;

    }


    .stat span {

        font-size: 6px;

    }


    .hero-card {

        width: 92%;

    }


    .floating-booking {

        left: -5px;

        min-width: 190px;

    }


    .floating-rating {

        right: -3px;

    }


    .section-heading h2,
    .about-content h2 {

        font-size: 29px;

    }


    .ground-image {

        height: 190px;

    }


    .cta-card {

        padding:
            34px 22px;

    }


    .cta-content h2 {

        font-size: 30px;

    }


    .footer-top {

        grid-template-columns:
            1fr;

    }


    .footer-brand {

        grid-column:
            auto;

    }

}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

a:focus-visible,
button:focus-visible {

    outline:
        3px solid
        rgba(108,92,231,0.45);

    outline-offset: 3px;

}


/* =========================================================
   SELECTION
   ========================================================= */

::selection {

    color: white;

    background:
        var(--primary);

}


/* =========================================================
   SCROLLBAR
   ========================================================= */

::-webkit-scrollbar {

    width: 8px;

}


::-webkit-scrollbar-track {

    background:
        #eef0f5;

}


::-webkit-scrollbar-thumb {

    border-radius: 20px;

    background:
        #c4c8d4;

}


::-webkit-scrollbar-thumb:hover {

    background:
        var(--primary);

}

